<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
require_once __DIR__.'/includes/profile-commerce-delivery-file-v1130.php';
require_permission('account.access');

$pdo=db();$user=current_user();if(!$pdo||!$user)redirect(url('/login.php'));if(!agent_commerce_schema_ready_v800($pdo))redirect(url('/upgrade.php'));
$uid=(int)$user['id'];$error='';$notice=trim((string)($_GET['saved']??''));
function profile_commerce_delivery_redirect_v1120(string $message): never{redirect(url('/profile-commerce-delivery.php?saved='.rawurlencode($message)));}
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!verify_csrf())$error='Session expired. Please try again.';
    else try{
        $action=(string)($_POST['action']??'');$orderId=(int)($_POST['order_id']??0);
        if($action==='save_delivery'){
            profile_commerce_delivery_save_v1120($pdo,$uid,$orderId,(string)($_POST['delivery_message']??''),(string)($_POST['resource_url']??''),(string)($_POST['resource_label']??''),(string)($_POST['fulfillment_state']??''));
            profile_commerce_delivery_redirect_v1120('Delivery details saved.');
        }
        if($action==='save_file'){
            profile_commerce_delivery_file_upload_v1130($pdo,$uid,$orderId,(array)($_FILES['delivery_file']??[]));
            profile_commerce_delivery_redirect_v1120('Private delivery file saved.');
        }
        if($action==='remove_file'){
            profile_commerce_delivery_file_remove_v1130($pdo,$uid,$orderId);
            profile_commerce_delivery_redirect_v1120('Private delivery file removed.');
        }
        throw new RuntimeException('Unknown delivery action.');
    }catch(Throwable $e){$error=$e->getMessage();}
}
$orders=[];foreach(profile_commerce_orders_for_owner_v900($pdo,$uid,120) as $order){if(profile_commerce_delivery_eligible_v1120($order))$orders[]=$order;}
