</style></head><body><div class="chat-app"><?php $workspaceSidebarUser=$user;$workspaceSidebarActive='commerce';require __DIR__.'/includes/workspace-sidebar-v82.php';?><div class="chat-sidebar-backdrop" id="chatSidebarBackdrop"></div><main class="chat-main pc-main"><?php $memberHeaderUser=$user;$memberHeaderTitle='Commerce Delivery';$memberHeaderSubtitle='Private digital and manual fulfillment for paid Profile Commerce orders';$memberHeaderActions='<a class="pc-btn" href="'.e(url('/profile-commerce-products.php')).'">Profile Commerce</a>';require __DIR__.'/includes/member-header.php';?><section class="pc-canvas"><div class="pc-inner"><div><span class="pc-eyebrow">Phase 11.3 · Secure delivery</span><h1>Deliver paid profile orders.</h1><p class="pc-muted">Messages, HTTPS resources, and one private file stay behind the buyer’s secure receipt token. Files are stored in denied private runtime storage and are never published as direct URLs.</p></div><?php if($notice!==''):?><div class="pc-notice"><?=e($notice)?></div><?php endif;?><?php if($error!==''):?><div class="pc-notice err" role="alert"><?=e($error)?></div><?php endif;?><?php if(!$orders):?><section class="pc-card"><h2>No paid deliverable orders</h2><p class="pc-muted">Eligible digital/manual orders appear here after payment is verified.</p></section><?php endif;?><?php foreach($orders as $order):$items=(array)($order['items']??[]);$item=$items[0]??[];$delivery=profile_commerce_delivery_v1120($order);$file=profile_commerce_delivery_file_metadata_v1130($order);$state=profile_commerce_fulfillment_state_v900($order);?><section class="pc-card"><div class="pc-order-head"><div><div class="pc-tags"><span class="pc-tag"><?=e((string)$order['payment_status'])?></span><span class="pc-tag"><?=e($state)?></span><span class="pc-tag"><?=e((string)$order['fulfillment_type'])?></span></div><h2><?=e((string)($item['title_snapshot']??$order['order_number']))?></h2><p class="pc-muted"><?=e((string)$order['order_number'])?> · <?=e(agent_commerce_money_v800((int)$order['amount_paid_cents'],(string)$order['currency']))?> paid<?php if(trim((string)$order['payer_email'])!==''):?> · <?=e((string)$order['payer_email'])?><?php endif;?></p></div><small class="pc-muted"><?=e((string)$order['updated_at'])?></small></div><form method="post" class="pc-form"><?=csrf_field()?><input type="hidden" name="action" value="save_delivery"><input type="hidden" name="order_id" value="<?=(int)$order['id']?>"><label class="wide">Delivery message<textarea name="delivery_message" maxlength="4000" placeholder="Access instructions, service completion note, pickup details, membership instructions…"><?=e((string)($delivery['message']??''))?></textarea></label><label>HTTPS resource<input type="url" name="resource_url" maxlength="2048" placeholder="https://…" value="<?=e((string)($delivery['resource_url']??''))?>"></label><label>Resource label<input name="resource_label" maxlength="80" placeholder="Open delivery resource" value="<?=e((string)($delivery['resource_label']??''))?>"></label><div class="wide pc-actions"><button class="pc-btn" type="submit" name="fulfillment_state" value="">Save delivery</button><?php if($state==='pending'):?><button class="pc-btn" type="submit" name="fulfillment_state" value="processing">Save + start processing</button><?php endif;?><?php if($state!=='fulfilled'):?><button class="pc-btn primary" type="submit" name="fulfillment_state" value="fulfilled">Save + mark fulfilled</button><?php endif;?></div></form><?php if($delivery):?><p class="pc-muted"><small>Private delivery updated <?=e((string)$delivery['updated_at'])?>.</small></p><?php endif;?><div class="pc-file"><div class="pc-eyebrow">Secure file delivery</div><?php if($file):?><div class="pc-file-meta"><div><strong><?=e((string)$file['original_name'])?></strong><div class="pc-muted"><small><?=e(profile_commerce_delivery_file_size_label_v1130((int)$file['bytes']))?> · <?=e((string)$file['mime'])?> · uploaded <?=e((string)$file['uploaded_at'])?></small></div></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="remove_file"><input type="hidden" name="order_id" value="<?=(int)$order['id']?>"><button class="pc-btn danger" type="submit">Remove file</button></form></div><?php else:?><p class="pc-muted">No private file attached. Buyers can download the attached file only through their secure receipt.</p><?php endif;?><form method="post" enctype="multipart/form-data" class="pc-file-form"><?=csrf_field()?><input type="hidden" name="action" value="save_file"><input type="hidden" name="order_id" value="<?=(int)$order['id']?>"><label><?= $file?'Replace private file':'Attach private file' ?><input type="file" name="delivery_file" required accept=".pdf,.zip,.txt,.csv,.json,.jpg,.jpeg,.png,.webp,.mp3,.wav,.mp4,.docx,.xlsx,.pptx"></label><button class="pc-btn" type="submit"><?= $file?'Replace file':'Upload file' ?></button></form><p class="pc-muted"><small>Maximum 50 MB. Files are MIME-checked, renamed to an opaque server ID, and stored outside public access under <code>private/</code>.</small></p></div></section><?php endforeach;?></div></section></main></div><script src="<?=e(url('/chat-shell-v82.js'))?>" defer></script></body></html>